import math


def count_Digit(n):
    """Write a python function to count the number of digits of a given number."""
    if isinstance(n, float):
        if not math.isfinite(n):
            raise ValueError("count_Digit() requires a finite number")
        n = int(abs(n))
    else:
        n = abs(n)

    if n == 0:
        return 1

    count = 0
    while n:
        count += 1
        n //= 10
    return count
